tool_input.command:
node --test test/ 2>&1 | tail -8 && node --input-type=module -e "
import { handle } from './src/api.js';
import { tick } from './src/scheduler.js';
const out = [];
for (const [tz, label] of [[330,'IST'],[-300,'EST'],[0,'UTC']]) {
  const { body } = handle({ method:'POST', path:'/reminders', body:{ userId:label, text:'call mum', at:'2026-03-01T09:00', tzOffsetMin: tz } });
  // find first minute tick() delivers it
  for (let t = Date.parse('2026-02-28T00:00:00Z'); t < Date.parse('2026-03-02T00:00:00Z'); t += 60000) {
    const before = out.length;
    await tick(t, { formatter: 'legacy', out: (l) => out.push(l) });
    if (out.length > before) { console.log(label, 'wants 09:00 local =', new Date(body.due_ms).toISOString(), '| fired at', new Date(t).toISOString(), '|', out.at(-1)); break; }
  }
}
const bad = handle({ method:'POST', path:'/reminders', body:{ userId:'x', text:'t', at:'2026-03-01T09:00:00' } });
console.log('bad at → status', bad.status, 'due_ms', bad.body.due_ms);
"
